'use client';

import { useEffect, useRef } from 'react';

export default function MouseSpotlight() {
  const ref = useRef<HTMLDivElement>(null);
  const rafId = useRef<number | null>(null);
  const mousePosition = useRef({ x: 0, y: 0 });

  useEffect(() => {
    let lastUpdate = 0;
    const throttleMs = 16; // Smoother 60fps-ish target

    const updateBackground = () => {
      if (typeof window === 'undefined') return;

      const now = performance.now();
      if (now - lastUpdate < throttleMs) {
        rafId.current = requestAnimationFrame(updateBackground);
        return;
      }
      lastUpdate = now;

      if (ref.current) {
        // Using N&N primary colors: var(--brand-dark) (dark blue) or var(--brand-gold) (gold)
        // Let's use a subtle gold/orange burst to match the premium theme
        ref.current.style.background = `radial-gradient(800px circle at ${mousePosition.current.x.toFixed(1)}px ${mousePosition.current.y.toFixed(1)}px, rgba(var(--brand-gold-rgb), 0.05), rgba(var(--brand-gold-rgb), 0) 150px)`;
      }
      rafId.current = requestAnimationFrame(updateBackground);
    };

    const handleMouseMove = (e: MouseEvent) => {
      mousePosition.current = { x: e.clientX, y: e.clientY };
      if (rafId.current === null) {
        rafId.current = requestAnimationFrame(updateBackground);
      }
    };

    window.addEventListener('mousemove', handleMouseMove, { passive: true });
    rafId.current = requestAnimationFrame(updateBackground);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      if (rafId.current !== null) {
        cancelAnimationFrame(rafId.current);
      }
    };
  }, []);

  return (
    <div
      ref={ref}
      className="pointer-events-none fixed inset-0 z-[100] hidden md:block"
      style={{
        willChange: 'background',
        contain: 'layout style paint',
      }}
    />
  );
}

import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { Navbar } from '../Navbar';

describe('Navbar', () => {
  it('renders logo and desktop links', () => {
    render(<Navbar />);
    expect(screen.getByText(/N&N POULTRY/i)).toBeInTheDocument();
    expect(screen.getByText(/PALACE/i)).toBeInTheDocument();
    
    expect(screen.getAllByText(/About/i)[0]).toBeInTheDocument();
    expect(screen.getAllByText(/Products/i)[0]).toBeInTheDocument();
  });

  it('toggles mobile menu when hamburger is clicked', () => {
    render(<Navbar />);
    const toggleButton = screen.getByLabelText(/Toggle mobile menu/i);
    
    // Initially menu should be hidden (check aria-expanded or style)
    expect(toggleButton).toHaveAttribute('aria-expanded', 'false');
    
    // Click to open
    fireEvent.click(toggleButton);
    expect(toggleButton).toHaveAttribute('aria-expanded', 'true');
    
    // In mobile menu, we should see links (there are two sets, desktop and mobile)
    // Mobile menu links are 3xl/4xl text
    const mobileLinks = screen.getAllByRole('link', { name: /About/i });
    expect(mobileLinks.length).toBeGreaterThan(1);
    
    // Click to close
    fireEvent.click(toggleButton);
    expect(toggleButton).toHaveAttribute('aria-expanded', 'false');
  });

  it('scrolls to top when logo is clicked', () => {
    const scrollToSpy = vi.fn();
    window.scrollTo = scrollToSpy;
    
    render(<Navbar />);
    const logo = screen.getByLabelText(/Home/i);
    fireEvent.click(logo);
    
    expect(scrollToSpy).toHaveBeenCalledWith({ top: 0, behavior: 'smooth' });
  });

  it('toggles theme when button is clicked', () => {
    // Note: useTheme is mocked in setup.ts to return theme: 'light', resolvedTheme: 'light'
    render(<Navbar />);
    const themeButtons = screen.getAllByLabelText(/Toggle theme/i);
    // Desktop toggle button
    const desktopToggle = themeButtons[0];
    expect(desktopToggle).toBeDefined();
    
    // Test that it can be clicked
    fireEvent.click(desktopToggle!);
  });
});

