'use client';

import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useRef, useEffect } from 'react';
import Image from 'next/image';
import type { Product } from '@/types/product';

gsap.registerPlugin(ScrollTrigger);

interface ProductCardProps {
  product: Product;
  index: number;
  isMobile: boolean;
}

export function ProductCard({ product, index, isMobile }: ProductCardProps) {
  const rangeStart = index * 0.3;
  const rangeEnd = (index + 1) * 0.3;

  const enterStart =
    index === 0 ? (isMobile ? 0.02 : 0.02) : isMobile ? rangeStart - 0.05 : rangeStart - 0.1;
  const enterEnd =
    index === 0 ? (isMobile ? 0.12 : 0.15) : isMobile ? rangeStart + 0.03 : rangeStart + 0.05;
  const exitStart = isMobile ? rangeEnd - 0.03 : rangeEnd - 0.05;
  const exitEnd = isMobile ? rangeEnd + 0.05 : rangeEnd + 0.05;

  const cardRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const titleRef = useRef<HTMLHeadingElement>(null);
  const paraRef = useRef<HTMLParagraphElement>(null);
  const detailsRef = useRef<HTMLDivElement>(null);
  const imageRef = useRef<HTMLDivElement>(null);

  const mousePos = useRef({ x: 0, y: 0 });
  const contentRotateX = useRef(0);
  const contentRotateY = useRef(0);

  const lerp = (start: number, end: number, t: number) => start + (end - start) * t;
  const mapRange = (
    value: number,
    inMin: number,
    inMax: number,
    outMin: number,
    outMax: number,
  ) => {
    if (value <= inMin) return outMin;
    if (value >= inMax) return outMax;
    const t = (value - inMin) / (inMax - inMin);
    return lerp(outMin, outMax, t);
  };

  const getValue = (progress: number, ranges: number[], values: number[]): number => {
    if (!ranges.length || !values.length) return 0;
    if (progress <= ranges[0]!) return values[0]!;
    if (progress >= ranges[ranges.length - 1]!) return values[values.length - 1]!;

    for (let i = 0; i < ranges.length - 1; i++) {
        const minValue = ranges[i]!;
        const maxValue = ranges[i + 1]!;
        const outMin = values[i]!;
        const outMax = values[i + 1]!;

        if (progress >= minValue && progress <= maxValue) {
            return mapRange(progress, minValue, maxValue, outMin, outMax);
        }
    }
    return values[0]!;
  };

  useEffect(() => {
    if (!cardRef.current) return;

    const ctx = gsap.context(() => {
      const container = cardRef.current?.closest('section');
      if (!container) return;

      let targetRotateX = 0;
      let targetRotateY = 0;
      let rafId: number | null = null;

      const updateMouseRotation = () => {
        if (contentRef.current && !isMobile) {
          contentRotateX.current = lerp(contentRotateX.current, targetRotateX, 0.1);
          contentRotateY.current = lerp(contentRotateY.current, targetRotateY, 0.1);

          gsap.set(contentRef.current, {
            rotateX: contentRotateX.current,
            rotateY: contentRotateY.current,
          });
        }

        if (
          Math.abs(contentRotateX.current - targetRotateX) > 0.01 ||
          Math.abs(contentRotateY.current - targetRotateY) > 0.01
        ) {
          rafId = requestAnimationFrame(updateMouseRotation);
        } else {
          rafId = null;
        }
      };

      const handleMouseMove = (e: MouseEvent) => {
        if (!cardRef.current || isMobile) return;

        if (!rafId) {
          rafId = requestAnimationFrame(() => {
            if (!cardRef.current) return;

            const rect = cardRef.current.getBoundingClientRect();
            const centerX = rect.left + rect.width / 2;
            const centerY = rect.top + rect.height / 2;

            mousePos.current = {
              x: e.clientX - centerX,
              y: e.clientY - centerY,
            };

            targetRotateX = mapRange(mousePos.current.y, -300, 300, 5, -5);
            targetRotateY = mapRange(mousePos.current.x, -300, 300, -5, 5);

            updateMouseRotation();
            rafId = null;
          });
        }
      };


      ScrollTrigger.create({
        trigger: container,
        start: 'top bottom',
        end: 'bottom top',
        scrub: true,
        onUpdate: (self: ScrollTrigger) => {
          const p = self.progress;

          const opacity = getValue(p, [enterStart, enterEnd, exitStart, exitEnd], [0, 1, 1, 0]);

          const x = isMobile
            ? 0
            : getValue(p, [enterStart, enterEnd, exitStart, exitEnd], [1920, 96, -96, -1920]);
          const y = isMobile
            ? getValue(p, [enterStart, enterEnd, exitStart, exitEnd], [100, 0, 0, -100])
            : getValue(p, [enterStart, enterEnd, exitStart, exitEnd], [540, 22, -22, -540]);
          const rotateY = isMobile
            ? 0
            : getValue(p, [enterStart, enterEnd, exitStart, exitEnd], [45, 5, -5, -45]);
          const rotateZ = isMobile
            ? 0
            : getValue(p, [enterStart, enterEnd, exitStart, exitEnd], [10, 2, -2, -10]);
          const z = isMobile
            ? 0
            : getValue(p, [enterStart, enterEnd, exitStart, exitEnd], [-1200, 0, 100, -1200]);
          const scale = isMobile
            ? getValue(p, [enterStart, enterEnd, exitStart, exitEnd], [0.9, 1, 1, 0.9])
            : getValue(p, [enterStart, enterEnd, exitStart, exitEnd], [0.6, 1, 1.05, 0.6]);

          const contentParallaxX = isMobile ? 0 : mapRange(p, enterStart, exitEnd, 100, -100);
          const titleParallaxX = isMobile ? 0 : mapRange(p, enterStart, exitEnd, 200, -200);

          if (cardRef.current) {
            gsap.set(cardRef.current, {
              opacity,
              x,
              y,
              rotateY,
              rotateZ,
              z,
              scale,
              transformPerspective: 1000,
              zIndex: 10 - index,
            });
          }

          if (titleRef.current) {
            gsap.set(titleRef.current, {
              x: titleParallaxX,
              translateZ: 40,
            });
          }

          if (paraRef.current) {
            gsap.set(paraRef.current, {
              x: contentParallaxX,
              translateZ: 30,
            });
          }

          if (detailsRef.current) {
            gsap.set(detailsRef.current, {
              x: contentParallaxX,
              translateZ: 25,
            });
          }

          if (imageRef.current) {
            gsap.set(imageRef.current, {
              translateZ: 50,
              rotateY: contentParallaxX / 10,
            });
          }
        },
      });

      if (cardRef.current && !isMobile) {
        cardRef.current.addEventListener('mousemove', handleMouseMove as EventListener, { passive: true });
      }

      return () => {
        if (cardRef.current) {
          cardRef.current.removeEventListener('mousemove', handleMouseMove as EventListener);
        }
        if (rafId) {
          cancelAnimationFrame(rafId);
        }
      };
    }, cardRef);

    return () => { ctx.revert(); };
  }, [index, isMobile]);

  return (
    <div
      ref={cardRef}
      className="absolute top-52 md:top-auto w-[92vw] sm:w-[85vw] max-w-6xl h-auto md:h-[65vh] flex flex-col md:flex-row overflow-visible rounded-3xl bg-card dark:bg-brand-dark shadow-2xl origin-center preserve-3d perspective-1000 border border-border dark:border-white/10"
      style={{
        willChange: 'transform, opacity',
      }}
    >
      <div
        ref={contentRef}
        className="flex-1 p-8 md:p-12 flex flex-col justify-center relative z-10 preserve-3d"
      >
        <h3
          ref={titleRef}
          className="text-foreground dark:text-white text-2xl md:text-5xl lg:text-6xl font-black mb-4 md:mb-6 tracking-tight preserve-3d"
        >
          {product.title}{' '}
          <span className="text-brand-gold">
            {product.titleAccent}
          </span>
        </h3>

        <p
          ref={paraRef}
          className="text-foreground/80 dark:text-gray-300 text-base md:text-lg lg:text-xl leading-relaxed mb-6 md:mb-8 preserve-3d"
        >
          {product.description}
        </p>

        <div
          ref={detailsRef}
          className="flex flex-col gap-3 preserve-3d"
        >
          {product.details.map((detail, i) => (
            <div
              key={i}
              className="flex items-start gap-3 text-foreground/70 dark:text-gray-400 text-sm md:text-base lg:text-lg font-medium"
            >
              <span className="mt-1 text-brand-gold">Γ£ª</span>
              <span>{detail}</span>
            </div>
          ))}
        </div>
      </div>

      <div
        className="flex-1 relative flex items-center justify-center p-8 overflow-hidden md:overflow-visible preserve-3d"
      >
        <div
          ref={imageRef}
          className="relative w-full h-[300px] md:h-full flex items-center justify-center pointer-events-none drop-shadow-2xl"
        >
          <Image
            src={product.image}
            alt={product.title}
            className="object-contain max-w-[120%] max-h-[120%] scale-110"
            fill
            sizes="(max-width: 768px) 90vw, 50vw"
            priority={index === 0}
            quality={85}
          />
        </div>
      </div>
    </div>
  );
}

'use client';

import { products } from '@/content/products';
import Image from 'next/image';
import { CheckCircle2 } from 'lucide-react';
import { motion } from 'motion/react';
import { useEffect } from 'react';

export function ProductsDetailed() {
  useEffect(() => {
    const handleScroll = () => {
      const hash = window.location.hash;
      if (hash) {
        const targetElement = document.querySelector(hash);
        if (targetElement) {
          // Calculate offset: navbar height (80px) + extra padding (40px)
          const offset = 120;
          const elementPosition = targetElement.getBoundingClientRect().top;
          const offsetPosition = elementPosition + window.pageYOffset - offset;

          window.scrollTo({
            top: offsetPosition,
            behavior: 'smooth'
          });
        }
      }
    };

    // Run on mount
    const timeoutId = setTimeout(handleScroll, 500);

    // Also listen for hash changes
    window.addEventListener('hashchange', handleScroll);
    return () => {
      clearTimeout(timeoutId);
      window.removeEventListener('hashchange', handleScroll);
    };
  }, []);

  return (
    <section id="products" className="py-16 md:py-24 bg-background">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 space-y-24 md:space-y-36">
        {products.map((product, index) => {
          const isEven = index % 2 === 0;
          return (
            <motion.div
              key={product.id}
              id={product.id}
              initial={{ opacity: 0, y: 48 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, margin: '-80px' }}
              transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
              className={`grid lg:grid-cols-2 gap-12 lg:gap-16 items-center ${
                isEven ? '' : 'lg:[&>*:first-child]:order-2'
              }`}
            >
              {/* Image (Desktop Only) */}
              <div className="hidden lg:flex relative aspect-square bg-brand-dark/60 rounded-[3rem] border border-white/10 items-center justify-center overflow-hidden group shadow-2xl">
                <div
                  className="absolute inset-0 opacity-20"
                  style={{
                    background: `radial-gradient(ellipse at center, ${product.color} 0%, transparent 70%)`,
                  }}
                />
                <Image
                  src={product.image}
                  alt={`${product.title} ${product.titleAccent}`}
                  fill
                  className="object-contain p-10 group-hover:scale-105 transition-transform duration-700"
                  sizes="50vw"
                  priority={index === 0}
                />
              </div>

              {/* Content / Mobile Background */}
              <div className="relative space-y-8 p-8 md:p-12 lg:p-0 rounded-[2.5rem] overflow-hidden lg:overflow-visible">
                {/* Mobile Background Image (Only visible < lg) */}
                <div className="absolute inset-0 lg:hidden -z-10">
                  <Image
                    src={product.image}
                    alt=""
                    fill
                    className="object-contain opacity-15 scale-110 blur-[2px]"
                  />
                  <div className="absolute inset-0 bg-gradient-to-b from-background/90 via-background/70 to-background/90" />
                </div>
                {/* Product Number */}
                <span
                  className="text-7xl md:text-8xl font-black leading-none select-none"
                  style={{
                    WebkitTextStroke: '1px rgba(255,255,255,0.1)',
                    WebkitTextFillColor: 'transparent',
                  }}
                >
                  0{index + 1}
                </span>

                <div>
                  <h2 className="text-4xl md:text-5xl xl:text-6xl font-black uppercase tracking-tight leading-none mb-4">
                    {product.title}{' '}
                    <span className="text-brand-gold">{product.titleAccent}</span>
                  </h2>
                  <p className="text-lg md:text-xl text-gray-300 leading-relaxed italic">
                    {product.fullDescription || product.description}
                  </p>
                </div>

                {/* Key Features */}
                {product.features && product.features.length > 0 && (
                  <div className="space-y-3">
                    <h3 className="text-xs font-bold uppercase tracking-widest text-brand-gold">
                      Key Features
                    </h3>
                    <ul className="space-y-3">
                      {product.features.map((feature, i) => (
                        <li key={i} className="flex items-center gap-3 text-base md:text-lg font-medium text-white">
                          <CheckCircle2 className="w-5 h-5 text-brand-gold flex-shrink-0" />
                          {feature}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </div>
            </motion.div>
          );
        })}
      </div>
    </section>
  );
}

'use client';

import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useGSAP } from '@gsap/react';
import type { MouseEvent} from 'react';
import { useRef } from 'react';
import { useIsMobile } from '@/hooks/use-is-mobile';

gsap.registerPlugin(ScrollTrigger, useGSAP);

interface HoverCardClientWrapperProps {
  children: React.ReactNode;
  index: number;
  className?: string;
}

export function HoverCardClientWrapper({ children, index, className }: HoverCardClientWrapperProps) {
  const cardRef = useRef<HTMLDivElement>(null);
  const spotlightRef = useRef<HTMLDivElement>(null);
  const glowRef = useRef<HTMLDivElement>(null);
  const rafId = useRef<number | null>(null);
  const lastUpdate = useRef(0);
  const isMobile = useIsMobile();

  useGSAP(() => {
    if (!cardRef.current) return;

    gsap.set(cardRef.current, {
      opacity: 0,
      y: 50,
      rotateY: 30,
    });

    ScrollTrigger.create({
      trigger: cardRef.current,
      start: 'top bottom-=100px',
      onEnter: () => {
        gsap.to(cardRef.current, {
          opacity: 1,
          y: 0,
          rotateY: 0,
          duration: 0.8,
          delay: index * 0.2,
          ease: 'back.out(1.7)',
        });
      },
    });

    if (!isMobile && cardRef.current) {
      const card = cardRef.current;

      const handleMouseEnter = () => {
        gsap.to(card, { scale: 1.05, duration: 0.3, ease: 'power2.out' });
        if (spotlightRef.current) gsap.to(spotlightRef.current, { opacity: 1, duration: 0.3 });
        if (glowRef.current) gsap.to(glowRef.current, { opacity: 1, duration: 0.3 });
      };

      const handleMouseLeave = () => {
        gsap.to(card, { scale: 1, rotateX: 0, rotateY: 0, duration: 0.3, ease: 'power2.out' });
        if (spotlightRef.current) gsap.to(spotlightRef.current, { opacity: 0, duration: 0.3 });
        if (glowRef.current) gsap.to(glowRef.current, { opacity: 0, duration: 0.3 });
      };

      card.addEventListener('mouseenter', handleMouseEnter);
      card.addEventListener('mouseleave', handleMouseLeave);
    }
  }, { scope: cardRef, dependencies: [index, isMobile] });

  function handleMouseMove({ currentTarget, clientX, clientY }: MouseEvent<HTMLDivElement>) {
    if (isMobile || !cardRef.current) return;

    const now = performance.now();
    if (now - lastUpdate.current < 32) return;
    lastUpdate.current = now;

    if (rafId.current) cancelAnimationFrame(rafId.current);
    rafId.current = requestAnimationFrame(() => {
      if (!cardRef.current) return;
      const rect = currentTarget.getBoundingClientRect();
      const x = (clientX - rect.left) / rect.width;
      const y = (clientY - rect.top) / rect.height;

      gsap.to(cardRef.current, {
        rotateX: (y - 0.5) * -16,
        rotateY: (x - 0.5) * 16,
        translateZ: (y - 0.5) * 40,
        duration: 0.3,
        glowX: x * 100,
        glowY: y * 100,
        ease: 'power2.out',
        transformPerspective: 1000,
      });

      if (spotlightRef.current) {
        gsap.set(spotlightRef.current, {
          background: `radial-gradient(400px circle at ${x * 100}% ${y * 100}%, rgba(var(--brand-gold-rgb),0.2), transparent 70%)`,
        });
      }

      if (glowRef.current) {
        gsap.set(glowRef.current, {
          background: `radial-gradient(300px circle at ${x * 100}% ${y * 100}%, rgba(var(--brand-gold-rgb),0.15), transparent 60%)`,
        });
      }
    });
  }

  return (
    <div
      ref={cardRef}
      onMouseMove={handleMouseMove}
      style={{ transformStyle: 'preserve-3d', perspective: '1000px' }}
      className={`group relative p-6 md:p-8 rounded-2xl md:rounded-3xl bg-card dark:bg-brand-dark border border-border dark:border-white/10 hover:bg-accent dark:hover:bg-[#1a3f50] transition-colors backdrop-blur-sm cursor-pointer ${className || ''}`}
    >
      <div
        ref={spotlightRef}
        className="pointer-events-none absolute -inset-px opacity-0 rounded-2xl md:rounded-3xl"
      />
      <div
        ref={glowRef}
        className="pointer-events-none absolute -inset-1 opacity-0 rounded-2xl md:rounded-3xl"
        style={{ transform: 'translateZ(-10px)' }}
      />
      
      <div className="relative z-10" style={{ transform: 'translateZ(20px)' }}>
        {children}
      </div>
    </div>
  );
}

'use client';

import * as React from 'react';
import type * as LabelPrimitive from '@radix-ui/react-label';
import { Slot } from '@radix-ui/react-slot';
import {
  Controller,
  FormProvider,
  useFormContext,
  useFormState,
  type ControllerProps,
  type FieldPath,
  type FieldValues,
} from 'react-hook-form';

import { cn } from './utils';
import { Label } from './label';

const Form = FormProvider;

interface FormFieldContextValue<
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
> {
  name: TName;
}

const FormFieldContext = React.createContext<FormFieldContextValue>({} as FormFieldContextValue);

const FormField = <
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
>({
  ...props
}: ControllerProps<TFieldValues, TName>) => {
  return (
    <FormFieldContext.Provider value={{ name: props.name }}>
      <Controller {...props} />
    </FormFieldContext.Provider>
  );
};

const useFormField = () => {
  const fieldContext = React.useContext(FormFieldContext);
  const itemContext = React.useContext(FormItemContext);
  if (!itemContext) {
    throw new Error('useFormField should be used within <FormItem>');
  }

  const { getFieldState } = useFormContext();
  const formState = useFormState({ name: fieldContext.name });
  const fieldState = getFieldState(fieldContext.name, formState);

  const { id } = itemContext;

  return {
    id,
    name: fieldContext.name,
    formItemId: `${id}-form-item`,
    formDescriptionId: `${id}-form-item-description`,
    formMessageId: `${id}-form-item-message`,
    ...fieldState,
  };
};

interface FormItemContextValue {
  id: string;
}

const FormItemContext = React.createContext<FormItemContextValue>({} as FormItemContextValue);

function FormItem({ className, ...props }: React.ComponentProps<'div'>) {
  const id = React.useId();

  return (
    <FormItemContext.Provider value={{ id }}>
      <div data-slot="form-item" className={cn('grid gap-2', className)} {...props} />
    </FormItemContext.Provider>
  );
}

function FormLabel({ className, ...props }: React.ComponentProps<typeof LabelPrimitive.Root>) {
  const { error, formItemId } = useFormField();

  return (
    <Label
      data-slot="form-label"
      data-error={!!error}
      className={cn('data-[error=true]:text-destructive', className)}
      htmlFor={formItemId}
      {...props}
    />
  );
}

function FormControl({ ...props }: React.ComponentProps<typeof Slot>) {
  const { error, formItemId, formDescriptionId, formMessageId } = useFormField();

  return (
    <Slot
      data-slot="form-control"
      id={formItemId}
      aria-describedby={!error ? formDescriptionId : `${formDescriptionId} ${formMessageId}`}
      aria-invalid={!!error}
      {...props}
    />
  );
}

function FormDescription({ className, ...props }: React.ComponentProps<'p'>) {
  const { formDescriptionId } = useFormField();

  return (
    <p
      data-slot="form-description"
      id={formDescriptionId}
      className={cn('text-muted-foreground text-sm', className)}
      {...props}
    />
  );
}

function FormMessage({ className, ...props }: React.ComponentProps<'p'>) {
  const { error, formMessageId } = useFormField();
  const body = error ? String(error?.message ?? '') : props.children;

  if (!body) {
    return null;
  }

  return (
    <p
      data-slot="form-message"
      id={formMessageId}
      className={cn('text-destructive text-sm', className)}
      {...props}
    >
      {body}
    </p>
  );
}

export {
  useFormField,
  Form,
  FormItem,
  FormLabel,
  FormControl,
  FormDescription,
  FormMessage,
  FormField,
};

'use client';

import * as React from 'react';
import * as ProgressPrimitive from '@radix-ui/react-progress';

import { cn } from './utils';

function Progress({
  className,
  value,
  ...props
}: React.ComponentProps<typeof ProgressPrimitive.Root>) {
  return (
