import { useEffect, useState } from 'react';
import { cn } from './utils';
import Image from 'next/image';

interface ProductData {
  title: string;
  titleAccent: string;
  description: string;
  image: string;
  color: string;
  details: string[];
}

const Card = ({ i, product }: { i: number; product: ProductData }) => {
